protocol CustomerDao {                                  // protocol = DAO interface
  func find(id: Int64) throws -> Customer?
}
struct GRDBCustomerDao: CustomerDao {                   // value-type implementation
  let dbQueue: DatabaseQueue                            // injected store handle
  func find(id: Int64) throws -> Customer? {
    try dbQueue.read { db in try Customer.fetchOne(db, key: id) }   // row -> struct
  }
  func add(_ c: Customer) throws {
    try dbQueue.write { db in try c.insert(db) }
  }
}
